<script>
(function () {
'use strict';

/* ══════════════════════════════════════════════════════════════
   CACHE DE IMAGENS (LOGO + BANDEIRAS) COM EXPIRAÇÃO
   ══════════════════════════════════════════════════════════════ */
var IMG_CACHE_PREFIX = 'yoru_img_';
var IMG_CACHE_DURATION = 7 * 24 * 60 * 60 * 1000; // 7 dias

/**
 * Retorna a URL base64 do cache ou null se expirado/inexistente
 */
function getFromImageCache(url) {
    if (!url || !url.startsWith('http')) return null;
    try {
        var key = IMG_CACHE_PREFIX + btoa(url).replace(/[/+=]/g, '_');
        var raw = localStorage.getItem(key);
        if (!raw) return null;
        var entry = JSON.parse(raw);
        if (!entry || !entry.data) return null;
        if (Date.now() - entry.ts > IMG_CACHE_DURATION) {
            localStorage.removeItem(key);
            return null;
        }
        return entry.data; // já é base64 data:image/...
    } catch(e) { return null; }
}

/**
 * Salva no cache
 */
function saveToImageCache(url, dataUrl) {
    if (!url || !dataUrl) return;
    try {
        var key = IMG_CACHE_PREFIX + btoa(url).replace(/[/+=]/g, '_');
        var entry = { ts: Date.now(), data: dataUrl, url: url };
        localStorage.setItem(key, JSON.stringify(entry));
        // Limpa caches antigos se localStorage estiver cheio
        pruneImageCache();
    } catch(e) {
        // localStorage cheio? tenta limpar
        if (e.name === 'QuotaExceededError') {
            pruneImageCache(true); // força limpeza
            try { localStorage.setItem(key, JSON.stringify({ts:Date.now(),data:dataUrl})); } catch(e2){}
        }
    }
}

/**
 * Remove os caches mais antigos quando localStorage está cheio
 */
function pruneImageCache(forceHalf) {
    try {
        var keys = [];
        for (var i = 0; i < localStorage.length; i++) {
            var k = localStorage.key(i);
            if (k && k.startsWith(IMG_CACHE_PREFIX)) {
                try {
                    var raw = localStorage.getItem(k);
                    var e = JSON.parse(raw);
                    keys.push({ key: k, ts: e.ts || 0 });
                } catch(e) {}
            }
        }
        if (keys.length < 30 && !forceHalf) return; // não precisa limpar
        keys.sort(function(a,b){ return a.ts - b.ts; }); // mais antigos primeiro
        var removeCount = forceHalf ? Math.ceil(keys.length / 2) : Math.ceil(keys.length * 0.3);
        for (var j = 0; j < removeCount && j < keys.length; j++) {
            localStorage.removeItem(keys[j].key);
        }
    } catch(e) {}
}

/**
 * Busca imagem via fetch, converte pra base64 e cacheia.
 * Retorna Promise<string> (data URL ou null se falhar)
 */
function fetchAndCacheImage(url) {
    return new Promise(function(resolve) {
        if (!url || !url.startsWith('http')) { resolve(null); return; }
        // Tenta cache primeiro
        var cached = getFromImageCache(url);
        if (cached) { resolve(cached); return; }
        // Timeout de 8s para não travar a UI
        var controller = new AbortController();
        var timeoutId = setTimeout(function() { controller.abort(); }, 8000);
        fetch(url, { signal: controller.signal, mode: 'cors' })
            .then(function(response) {
                clearTimeout(timeoutId);
                if (!response.ok) { resolve(null); return; }
                return response.blob();
            })
            .then(function(blob) {
                if (!blob) { resolve(null); return; }
                var reader = new FileReader();
                reader.onloadend = function() {
                    var dataUrl = reader.result;
                    if (dataUrl && dataUrl.startsWith('data:image')) {
                        saveToImageCache(url, dataUrl);
                        resolve(dataUrl);
                    } else {
                        resolve(null);
                    }
                };
                reader.onerror = function() { resolve(null); };
                reader.readAsDataURL(blob);
            })
            .catch(function() {
                clearTimeout(timeoutId);
                resolve(null);
            });
    });
}

/**
 * Aplica imagem cacheada/baixada em um elemento <img> ou container.
 * @param {string} url - URL original da imagem
 * @param {HTMLElement|string} target - elemento ou ID do container
 * @param {string} fallbackHtml - HTML a aplicar se falhar (ex: emoji 🌍)
 */
function loadImageWithCache(url, target, fallbackHtml) {
    if (typeof target === 'string') target = document.getElementById(target);
    if (!target) return;
    // Se a URL já é local (file:// ou data:), usa direto
    if (url && (url.startsWith('file://') || url.startsWith('data:'))) {
        target.innerHTML = '<img src="' + esc(url) + '" style="width:100%;height:100%;object-fit:cover;">';
        return;
    }
    // Exibe placeholder enquanto carrega
    if (fallbackHtml) target.innerHTML = fallbackHtml;
    fetchAndCacheImage(url).then(function(dataUrl) {
        if (dataUrl) {
            target.innerHTML = '<img src="' + dataUrl + '" style="width:100%;height:100%;object-fit:cover;">';
        } else if (!fallbackHtml) {
            target.innerHTML = ''; // ou mantém o que já estava
        }
    });
}

/**
 * Helper para escapar strings no HTML (evita XSS)
 */
function esc(s) { 
    return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;'); 
}

/* ══════════════════════════════════════════════════════════════
   SOBRESCREVE refreshSelected() para usar cache de bandeiras
   ══════════════════════════════════════════════════════════════ */
function refreshSelected() {
    var s = A.getSelected();
    if (s && s.Name) {
        setText('server-title', s.Name || 'Servidor Automático');
        setText('server-sub', s.Info || 'Pronto para uso');
        var wrap = $('server-flag-wrap');
        if (wrap) {
            var src = s.FlagUrl || (s.Flag ? 'file:///android_asset/flags/' + s.Flag + '.png' : '');
            if (src) {
                loadImageWithCache(src, wrap, '🌍');
            } else {
                wrap.innerHTML = '🌍';
            }
        }
    } else {
        setText('server-title', 'Servidor Automático');
        setText('server-sub', 'Selecionar operadora');
    }
    // Multi / Dedicado — só se chip Multi ligado
    var pCard = $('select-premium');
    if (pCard) pCard.style.display = _uiShowMulti ? 'flex' : 'none';
    var multiList = A.getMultiServers() || [];
    var p = A.getSelectedMulti();
    if (p && p.Name) {
        setText('premium-title', p.Name);
        setText('premium-sub', p.Info || ('Multi · ' + multiList.length + ' redes'));
        var pwrap = $('premium-flag-wrap');
        if (pwrap) {
            var psrc = p.FlagUrl || (p.Flag ? 'file:///android_asset/flags/' + p.Flag + '.png' : '');
            if (psrc) {
                loadImageWithCache(psrc, pwrap, '🌐');
            } else {
                pwrap.innerHTML = '🌐';
            }
        }
    } else {
        setText('premium-title', multiList.length ? (multiList.length + ' redes multi') : 'Selecionar Multi');
        setText('premium-sub', multiList.length ? 'Toque para escolher multi/dedicado' : 'Nenhuma rede multi ainda');
    }
    try {
        var op = (s && s.Info) ? s.Info : getOperatorSafe();
        setText('header-operator', op || 'Operadora');
        setText('profile-operator', op || '—');
        setText('profile-server', (s && s.Name) ? s.Name : '—');
    } catch(e) {}
    updateCredentialsVisibility();
    updateProfileCard();
}

/* ══════════════════════════════════════════════════════════════
   SOBRESCREVE buildServerList() para usar cache nas bandeiras
   ══════════════════════════════════════════════════════════════ */
var originalBuildServerList = buildServerList;
function buildServerList(type) {
    var root = $('list-servers'); if (!root) return;
    root.innerHTML = '';
    var isMulti = (type === 'premium' || type === 'multi');
    var servers = isMulti ? A.getMultiServers() : A.getServers();
    var selected = isMulti ? A.getSelectedMulti() : A.getSelected();
    var selPos = selected ? selected.position : -1;
    var meta = getServersMeta(isMulti ? 'multi' : 'servers');
    var mTitle = document.querySelector('#modal-servers .modal-title');
    if (mTitle) mTitle.textContent = isMulti ? '🌐 Multi / Dedicado' : '🌍 Operadoras';

    var tabsHtml =
        '<div style="display:flex;gap:8px;margin-bottom:10px;">'+
          '<button type="button" id="tab-srv-free" style="flex:1;padding:10px;border-radius:12px;font-weight:700;font-size:12px;border:1px solid var(--border);background:'+(isMulti?'rgba(255,255,255,0.04)':'rgba(99,102,241,0.15)')+';color:var(--text-main);">🌍 Operadoras</button>'+
          '<button type="button" id="tab-srv-multi" style="flex:1;padding:10px;border-radius:12px;font-weight:700;font-size:12px;border:1px solid var(--border);background:'+(isMulti?'rgba(6,182,212,0.2)':'rgba(255,255,255,0.04)')+';color:var(--text-main);">🌐 Multi</button>'+
        '</div>';
    if (!isMulti) {
        tabsHtml +=
          '<div style="display:flex;gap:6px;margin-bottom:14px;">'+
            '<button type="button" class="srv-proto" data-f="all" style="flex:1;padding:8px;border-radius:10px;font-weight:700;font-size:11px;border:1px solid var(--border);background:'+(_srvListFilter==='all'?'rgba(99,102,241,0.2)':'rgba(255,255,255,0.04)')+';color:var(--text-main);">Todos</button>'+
            '<button type="button" class="srv-proto" data-f="ssh" style="flex:1;padding:8px;border-radius:10px;font-weight:700;font-size:11px;border:1px solid var(--border);background:'+(_srvListFilter==='ssh'?'rgba(16,185,129,0.2)':'rgba(255,255,255,0.04)')+';color:var(--text-main);">SSH</button>'+
            '<button type="button" class="srv-proto" data-f="xray" style="flex:1;padding:8px;border-radius:10px;font-weight:700;font-size:11px;border:1px solid var(--border);background:'+(_srvListFilter==='xray'?'rgba(168,85,247,0.2)':'rgba(255,255,255,0.04)')+';color:var(--text-main);">XRay</button>'+
          '</div>';
    }
    root.innerHTML = tabsHtml;
    var freeTab = document.getElementById('tab-srv-free');
    var multiTab = document.getElementById('tab-srv-multi');
    if (freeTab) freeTab.onclick = function() { buildServerList('normal'); };
    if (multiTab) multiTab.onclick = function() { buildServerList('multi'); };
    root.querySelectorAll('.srv-proto').forEach(function(btn) {
        btn.onclick = function() { _srvListFilter = btn.getAttribute('data-f') || 'all'; buildServerList('normal'); };
    });

    if (!servers || !servers.length) {
        var empty = document.createElement('div');
        empty.style.cssText = 'color:var(--text-muted);padding:24px;text-align:center;';
        empty.textContent = isMulti ? 'Nenhuma rede multi/dedicada.' : 'Lista de operadoras vazia.';
        root.appendChild(empty);
        return;
    }

    var shown = 0;
    servers.forEach(function(s, i) {
        var pos = s.position !== undefined ? s.position : i;
        var m = meta[pos] || meta[i] || { hasAuth: true, isXray: false };
        if (!isMulti) {
            if (_srvListFilter === 'ssh' && m.isXray) return;
            if (_srvListFilter === 'xray' && !m.isXray) return;
        }
        shown++;
        var isSel = (pos === selPos || i === selPos);
        var flagSrc = s.FlagUrl ? s.FlagUrl : (s.Flag ? 'file:///android_asset/flags/' + s.Flag + '.png' : '');
        var tagHtml;
        if (isMulti) {
            tagHtml = '<span class="sc-badge" style="margin-right:6px;background:rgba(6,182,212,0.18);color:#67e8f9;">MULTI</span>';
        } else if (m.hasAuth) {
            tagHtml = '<span class="sc-badge free" style="margin-right:6px;">FREE</span>';
        } else {
            tagHtml = '<span class="sc-badge vip" style="margin-right:6px;">PREMIUM</span>';
        }
        var protoHint = m.isXray ? 'XRay' : 'SSH';
        var el = document.createElement('div');
        el.className = 'list-item' + (isSel ? ' selected' : '');
        el.innerHTML =
            '<div class="li-icon" id="li-flag-' + (isMulti?'m':'s') + '-' + pos + '">' + 
            (isMulti ? '🌐' : '🌍') + 
            '</div>' +
            '<div class="li-main"><div class="li-title">' + esc(s.Name || 'Rede') + '</div>' +
            '<div class="li-sub">' + esc(s.Info || protoHint) + (isMulti ? '' : ' · ' + protoHint) + '</div></div>' +
            tagHtml +
            '<span class="li-check">✓</span>';
        el.onclick = function() {
            if (app.connected) { toast('Desconecte para trocar de rede.', 'err'); return; }
            autoSaveCredentials(true);
            if (isMulti) A.selectMultiServer(pos);
            else A.selectServer(pos);
            closeModal();
            setTimeout(function() { refreshSelected(); loadSavedCredentials(); }, 250);
            toast(isMulti ? 'Rede multi selecionada!' : 'Operadora selecionada!', 'ok');
        };
        root.appendChild(el);
        // Carrega bandeira com cache ASSÍNCRONO (não bloqueia a UI)
        if (flagSrc) {
            var flagId = 'li-flag-' + (isMulti ? 'm' : 's') + '-' + pos;
            loadImageWithCache(flagSrc, flagId, isMulti ? '🌐' : '🌍');
        }
    });
    if (!shown) {
        var none = document.createElement('div');
        none.style.cssText = 'color:var(--text-muted);padding:24px;text-align:center;';
        none.textContent = _srvListFilter === 'xray' ? 'Nenhuma operadora XRay nesta lista.' : 'Nenhuma operadora SSH nesta lista.';
        root.appendChild(none);
    }
}

/* ══════════════════════════════════════════════════════════════
   CACHE DO LOGO DO APP (avatar GitHub)
   ══════════════════════════════════════════════════════════════ */
function cacheAppLogo() {
    var LOGO_URL = 'https://avatars.githubusercontent.com/u/168665654?v=4&size=64';
    var logoContainers = document.querySelectorAll('.app-logo-icon img');
    // Se já está carregado nativamente, marca no cache
    logoContainers.forEach(function(img) {
        if (img.complete && img.naturalWidth > 0) {
            // Converte para data URL via canvas e salva
            try {
                var canvas = document.createElement('canvas');
                canvas.width = img.naturalWidth;
                canvas.height = img.naturalHeight;
                var ctx = canvas.getContext('2d');
                ctx.drawImage(img, 0, 0);
                var dataUrl = canvas.toDataURL('image/png');
                saveToImageCache(LOGO_URL, dataUrl);
            } catch(e) {}
        }
    });
    // Pré-carrega/cacheia para próximas aberturas
    fetchAndCacheImage(LOGO_URL).then(function(dataUrl) {
        if (dataUrl) {
            // Atualiza todos os logos na página com a versão cacheada
            document.querySelectorAll('.app-logo-icon').forEach(function(icon) {
                if (!icon.querySelector('img')) {
                    icon.innerHTML = '<img src="' + dataUrl + '" alt="Yoru" style="width:100%;height:100%;object-fit:cover;border-radius:12px;">';
                }
            });
        }
    });
}

/* ══════════════════════════════════════════════════════════════
   LIMPEZA PERIÓDICA DO CACHE (roda 1x por dia)
   ══════════════════════════════════════════════════════════════ */
function scheduleCacheMaintenance() {
    var LAST_CLEAN_KEY = 'yoru_cache_last_clean';
    var now = Date.now();
    var last = parseInt(localStorage.getItem(LAST_CLEAN_KEY) || '0');
    if (now - last > 24 * 60 * 60 * 1000) {
        // Remove caches expirados
        pruneImageCache(false);
        localStorage.setItem(LAST_CLEAN_KEY, String(now));
    }
}

/* ══════════════════════════════════════════════════════════════
   BOOT: injeta cache no fluxo normal
   ══════════════════════════════════════════════════════════════ */
function boot() {
    createBubbles(); 
    updateCelestial(); 
    loadTheme(); 
    loadLayout();
    bind(); 
    loadUiPrefs(); 
    applyCredsModeUI(); 
    loadRadical(); 
    initTimeCard();
    refreshInfo(); 
    refreshSelected(); 
    loadSavedCredentials(); 
    applyState(A.getStatus());
    startPolling();
    setInterval(function() { if (!app.busy) refreshInfo(); }, 30000);
    loadSettings();
    startFirebaseIntegration();
    // Cache do logo e manutenção
    setTimeout(cacheAppLogo, 1500);
    scheduleCacheMaintenance();
}

if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
else boot();

})();
</script>

